P01ProductRouter.java<pre><code>package com.example.reactive.playbook.codinginterview;

import jakarta.validation.Validator;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import java.net.URI;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.ServerRequest;
import org.springframework.web.reactive.function.server.ServerResponse;
import reactor.core.publisher.Mono;

import static org.springframework.web.reactive.function.server.RouterFunctions.route;

/** Problem 1: CRUD with FUNCTIONAL endpoints: explicit routing, manual validation, 201/404/400 as ProblemDetail. */
public class P01ProductRouter {

    public record CreateProduct(@NotBlank String name, @Positive long priceCents) { }
    public record Product(long id, String name, long priceCents) { }

    private final Map&lt;Long, Product&gt; store = new ConcurrentHashMap&lt;&gt;();
    private final AtomicLong ids = new AtomicLong();
    private final Validator validator;

    public P01ProductRouter(Validator validator) { this.validator = validator; }

    public RouterFunction&lt;ServerResponse&gt; routes() {
        return route()
                .path("/products", b -&gt; b
                        .GET("/{id}", this::get)
                        .POST("", this::create)
                        .DELETE("/{id}", this::delete))
                .build();
    }

    Mono&lt;ServerResponse&gt; create(ServerRequest req) {
        return req.bodyToMono(CreateProduct.class)
                .switchIfEmpty(Mono.error(new IllegalArgumentException("request body is required")))
                .flatMap(this::validate)                                       // validation is explicit in functional style
                .map(c -&gt; { Product p = new Product(ids.incrementAndGet(), c.name(), c.priceCents()); store.put(p.id(), p); return p; })
                .flatMap(p -&gt; ServerResponse.created(URI.create("/products/" + p.id())).bodyValue(p))
                .onErrorResume(IllegalArgumentException.class, e -&gt; problem(HttpStatus.BAD_REQUEST, e.getMessage()));
    }

    Mono&lt;ServerResponse&gt; get(ServerRequest req) {
        long id = Long.parseLong(req.pathVariable("id"));
        return Mono.justOrEmpty(store.get(id))
                .flatMap(p -&gt; ServerResponse.ok().bodyValue(p))
                .switchIfEmpty(Mono.defer(() -&gt; problem(HttpStatus.NOT_FOUND, "product " + id + " not found")));  // defer: build lazily
    }

    Mono&lt;ServerResponse&gt; delete(ServerRequest req) {
        store.remove(Long.parseLong(req.pathVariable("id")));
        return ServerResponse.noContent().build();
    }

    private Mono&lt;CreateProduct&gt; validate(CreateProduct c) {
        var violations = validator.validate(c);
        if (violations.isEmpty()) return Mono.just(c);
        String msg = violations.stream().map(v -&gt; v.getPropertyPath() + " " + v.getMessage()).sorted().collect(Collectors.joining("; "));
        return Mono.error(new IllegalArgumentException(msg));
    }

    private static Mono&lt;ServerResponse&gt; problem(HttpStatus status, String detail) {
        return ServerResponse.status(status).bodyValue(ProblemDetail.forStatusAndDetail(status, detail));
    }
}
</code></pre> P01ProductRouterTest.java<pre><code>package com.example.reactive.playbook.codinginterview;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.reactive.server.WebTestClient;
import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;

class P01ProductRouterTest {

    WebTestClient client;

    @BeforeEach
    void setUp() {
        var validator = new LocalValidatorFactoryBean();
        validator.afterPropertiesSet();
        client = WebTestClient.bindToRouterFunction(new P01ProductRouter(validator).routes()).build();
    }

    @Test
    void create_returns201_withLocation() {
        client.post().uri("/products").bodyValue(new P01ProductRouter.CreateProduct("Kettle", 2_500)).exchange()
              .expectStatus().isCreated()
              .expectHeader().valueMatches("Location", "/products/\\d+")
              .expectBody().jsonPath("$.name").isEqualTo("Kettle");
    }

    @Test
    void invalidBody_returns400_withEveryViolation() {
        client.post().uri("/products").bodyValue(new P01ProductRouter.CreateProduct("", -1)).exchange()
              .expectStatus().isBadRequest()
              .expectBody().jsonPath("$.detail").isEqualTo("name must not be blank; priceCents must be greater than 0");
    }

    @Test
    void missingProduct_returns404_problemDetail() {
        client.get().uri("/products/42").exchange()
              .expectStatus().isNotFound()
              .expectBody().jsonPath("$.detail").isEqualTo("product 42 not found");
    }

    @Test
    void roundTrip_createGetDelete() {
        String location = client.post().uri("/products").bodyValue(new P01ProductRouter.CreateProduct("Mug", 900)).exchange()
                .expectStatus().isCreated().returnResult(Void.class).getResponseHeaders().getLocation().toString();
        client.get().uri(location).exchange().expectStatus().isOk().expectBody().jsonPath("$.priceCents").isEqualTo(900);
        client.delete().uri(location).exchange().expectStatus().isNoContent();
        client.get().uri(location).exchange().expectStatus().isNotFound();
    }
}
