P02ProfileAggregator.java<pre><code>package com.example.reactive.playbook.codinginterview;

import java.time.Duration;
import java.util.List;
import org.springframework.web.reactive.function.client.WebClient;
import org.springframework.web.reactive.function.client.WebClientResponseException;
import reactor.core.publisher.Mono;

/** Problem 2: fan out to 3 services with WebClient in parallel; required vs optional calls; timeouts + fallbacks. */
public class P02ProfileAggregator {

    public record User(String id, String name) { }
    public record Order(String id, long cents) { }
    public record Profile(User user, List&lt;Order&gt; recentOrders, int loyaltyPoints, List&lt;String&gt; degraded) { }

    private final WebClient http;
    private final Duration optionalTimeout;

    public P02ProfileAggregator(WebClient http, Duration optionalTimeout) { this.http = http; this.optionalTimeout = optionalTimeout; }

    public Mono&lt;Profile&gt; profile(String userId) {
        Mono&lt;User&gt; user = http.get().uri("/users/{id}", userId).retrieve().bodyToMono(User.class);   // required: errors propagate

        Mono&lt;Result&lt;List&lt;Order&gt;&gt;&gt; orders = http.get().uri("/orders?user={id}", userId).retrieve()
                .bodyToFlux(Order.class).take(3).collectList()
                .timeout(optionalTimeout)
                .map(Result::ok)
                .onErrorResume(e -&gt; Mono.just(Result.fallback(List.of(), "orders: " + reason(e))));

        Mono&lt;Result&lt;Integer&gt;&gt; points = http.get().uri("/loyalty/{id}", userId).retrieve().bodyToMono(Integer.class)
                .timeout(optionalTimeout)
                .map(Result::ok)
                .onErrorResume(e -&gt; Mono.just(Result.fallback(0, "loyalty: " + reason(e))));

        // zip subscribes to all three at once: latency = slowest call, not the sum
        return Mono.zip(user, orders, points).map(t -&gt; new Profile(t.getT1(), t.getT2().value(), t.getT3().value(),
                java.util.stream.Stream.of(t.getT2().degraded(), t.getT3().degraded()).filter(java.util.Objects::nonNull).toList()));
    }

    private static String reason(Throwable e) {
        if (e instanceof java.util.concurrent.TimeoutException) return "timeout";
        if (e instanceof WebClientResponseException w) return String.valueOf(w.getStatusCode().value());
        return e.getClass().getSimpleName();
    }

    record Result&lt;T&gt;(T value, String degraded) {
        static &lt;T&gt; Result&lt;T&gt; ok(T v) { return new Result&lt;&gt;(v, null); }
        static &lt;T&gt; Result&lt;T&gt; fallback(T v, String why) { return new Result&lt;&gt;(v, why); }
    }
}
</code></pre> P02ProfileAggregatorTest.java<pre><code>package com.example.reactive.playbook.codinginterview;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.web.reactive.function.client.ClientResponse;
import org.springframework.web.reactive.function.client.WebClient;
import org.springframework.web.reactive.function.client.WebClientResponseException;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;

/** WebClient with a stubbed ExchangeFunction: real request/response/decoding, no network, no mock server. */
class P02ProfileAggregatorTest {

    static WebClient stub(Map&lt;String, Function&lt;String, Mono&lt;ClientResponse&gt;&gt;&gt; routes) {
        return WebClient.builder().exchangeFunction(req -&gt; {
            String path = req.url().getPath();
            return routes.entrySet().stream().filter(e -&gt; path.startsWith(e.getKey())).findFirst()
                    .map(e -&gt; e.getValue().apply(path)).orElse(Mono.just(ClientResponse.create(HttpStatus.NOT_FOUND).build()));
        }).build();
    }

    static Mono&lt;ClientResponse&gt; json(String body, long delayMs) {
        return Mono.delay(Duration.ofMillis(delayMs)).map(x -&gt; ClientResponse.create(HttpStatus.OK).header("Content-Type", "application/json").body(body).build());
    }

    @Test
    void allHealthy_returnsFullProfile_inParallel() {
        var agg = new P02ProfileAggregator(stub(Map.of(
                "/users", p -&gt; json("{\"id\":\"u1\",\"name\":\"Ana\"}", 100),
                "/orders", p -&gt; json("[{\"id\":\"o1\",\"cents\":500},{\"id\":\"o2\",\"cents\":700}]", 100),
                "/loyalty", p -&gt; json("120", 100))), Duration.ofSeconds(1));
        long start = System.nanoTime();
        StepVerifier.create(agg.profile("u1"))
                .assertNext(p -&gt; {
                    assertThat(p.user().name()).isEqualTo("Ana");
                    assertThat(p.recentOrders()).hasSize(2);
                    assertThat(p.loyaltyPoints()).isEqualTo(120);
                    assertThat(p.degraded()).isEmpty();
                }).verifyComplete();
        assertThat(Duration.ofNanos(System.nanoTime() - start)).isLessThan(Duration.ofMillis(290));   // ~100 ms, not 300
    }

    @Test
    void slowAndFailingOptionalServices_degradeGracefully() {
        var agg = new P02ProfileAggregator(stub(Map.of(
                "/users", p -&gt; json("{\"id\":\"u1\",\"name\":\"Ana\"}", 10),
                "/orders", p -&gt; json("[]", 5_000),
                "/loyalty", p -&gt; Mono.just(ClientResponse.create(HttpStatus.SERVICE_UNAVAILABLE).build()))), Duration.ofMillis(200));
        StepVerifier.create(agg.profile("u1"))
                .assertNext(p -&gt; {
                    assertThat(p.recentOrders()).isEmpty();
                    assertThat(p.loyaltyPoints()).isZero();
                    assertThat(p.degraded()).containsExactly("orders: timeout", "loyalty: 503");
                }).verifyComplete();
    }

    @Test
    void requiredServiceFailure_failsTheWholeProfile() {
        var agg = new P02ProfileAggregator(stub(Map.of(
                "/orders", p -&gt; json("[]", 10), "/loyalty", p -&gt; json("1", 10))), Duration.ofSeconds(1));   // /users -&gt; 404
        StepVerifier.create(agg.profile("nobody")).expectError(WebClientResponseException.NotFound.class).verify();
    }
}
</code></pre>

P03BlockingBridge.java<pre><code>package com.example.reactive.playbook.codinginterview;

import java.time.Duration;
import java.util.function.Function;
import reactor.core.publisher.Mono;
import reactor.core.scheduler.Scheduler;
import reactor.core.scheduler.Schedulers;

/** Problem 3: call a BLOCKING legacy client (JDBC, SOAP SDK) from WebFlux without blocking the event loop. */
public class P03BlockingBridge {

    /** The legacy API: blocks the calling thread. */
    public interface LegacyCustomerClient { String loadCustomer(String id); }

    private final LegacyCustomerClient legacy;
    private final Scheduler blockingPool;

    public P03BlockingBridge(LegacyCustomerClient legacy, Scheduler blockingPool) { this.legacy = legacy; this.blockingPool = blockingPool; }

    /**
     * fromCallable = lazy (runs per subscription), subscribeOn = WHERE it runs (a bounded pool for blocking work),
     * timeout = never wait forever on legacy I/O.
     */
    public Mono&lt;String&gt; customer(String id) {
        return Mono.fromCallable(() -&gt; legacy.loadCustomer(id))
                .subscribeOn(blockingPool)
                .timeout(Duration.ofSeconds(2));
    }

    /** WRONG (for contrast): Mono.just evaluates eagerly on the CALLER's thread, i.e. the event loop. */
    public Mono&lt;String&gt; customerWrong(String id) { return Mono.just(legacy.loadCustomer(id)); }

    /** A dedicated, bounded pool: a slow legacy system can't exhaust the shared boundedElastic for everyone. */
    public static Scheduler dedicatedPool() { return Schedulers.newBoundedElastic(10, 100, "legacy-crm"); }

    public static Function&lt;String, String&gt; threadName() { return s -&gt; s + " on " + Thread.currentThread().getName().replaceAll("-\\d+$", "-N"); }
}
</code></pre> P03BlockingBridgeTest.java<pre><code>package com.example.reactive.playbook.codinginterview;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import reactor.core.scheduler.Schedulers;
import reactor.test.StepVerifier;

class P03BlockingBridgeTest {

    final AtomicReference&lt;String&gt; ranOn = new AtomicReference&lt;&gt;();
    final AtomicInteger calls = new AtomicInteger();
    final P03BlockingBridge.LegacyCustomerClient legacy = id -&gt; {
        calls.incrementAndGet();
        ranOn.set(Thread.currentThread().getName());
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return "customer " + id;
    };

    @Test
    void blockingCall_runsOnTheDedicatedPool_notTheCaller() {
        var pool = P03BlockingBridge.dedicatedPool();
        try {
            StepVerifier.create(new P03BlockingBridge(legacy, pool).customer("c1")).expectNext("customer c1").verifyComplete();
            assertThat(ranOn.get()).startsWith("legacy-crm-");
        } finally { pool.dispose(); }
    }

    @Test
    void fromCallable_isLazy_nothingRunsUntilSubscribe() {
        Mono&lt;String&gt; mono = new P03BlockingBridge(legacy, Schedulers.boundedElastic()).customer("c2");
        assertThat(calls.get()).isZero();
        mono.block();
        mono.block();
        assertThat(calls.get()).isEqualTo(2);                  // runs once PER subscription
    }

    @Test
    void monoJust_blocksTheCallerAtAssemblyTime() {
        new P03BlockingBridge(legacy, Schedulers.boundedElastic()).customerWrong("c3");   // never subscribed!
        assertThat(calls.get()).isEqualTo(1);
        assertThat(ranOn.get()).isEqualTo(Thread.currentThread().getName());              // ran on the caller's thread
    }

    @Test
    void manyConcurrentCalls_doNotSerialise() {
        var pool = P03BlockingBridge.dedicatedPool();
        try {
            long start = System.nanoTime();
            var bridge = new P03BlockingBridge(legacy, pool);
            StepVerifier.create(reactor.core.publisher.Flux.range(1, 10).flatMap(i -&gt; bridge.customer("c" + i)).count())
                    .expectNext(10L).verifyComplete();
            assertThat((System.nanoTime() - start) / 1_000_000).isLessThan(400);         // 10 x 50 ms in parallel, not 500 ms
        } finally { pool.dispose(); }
    }
}
</code></pre>

P04Backpressure.java<pre><code>package com.example.reactive.playbook.codinginterview;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import reactor.core.publisher.BufferOverflowStrategy;
import reactor.core.publisher.Flux;

/** Problem 4: a producer that ignores demand (sensor/clicks) vs a slow consumer: buffer, drop or keep latest. */
public class P04Backpressure {

    public final List&lt;Integer&gt; dropped = new CopyOnWriteArrayList&lt;&gt;();

    /** Keep up to `size` waiting items; beyond that, drop the OLDEST and record it (bounded memory, lossy). */
    public Flux&lt;Integer&gt; bounded(Flux&lt;Integer&gt; hot, int size) {
        return hot.onBackpressureBuffer(size, dropped::add, BufferOverflowStrategy.DROP_OLDEST);
    }

    /** Drop whatever arrives while the consumer has no outstanding demand. */
    public Flux&lt;Integer&gt; drop(Flux&lt;Integer&gt; hot) { return hot.onBackpressureDrop(dropped::add); }

    /** Only the most recent value matters (price, position): keep the latest, discard older unconsumed ones. */
    public Flux&lt;Integer&gt; latest(Flux&lt;Integer&gt; hot) { return hot.onBackpressureLatest(); }

    /** A cold source that DOES honour demand: ask in batches of 10 with a 75% replenish threshold. */
    public Flux&lt;Integer&gt; paced(Flux&lt;Integer&gt; cold) { return cold.limitRate(10); }
}
</code></pre> P04BackpressureTest.java<pre><code>package com.example.reactive.playbook.codinginterview;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import org.junit.jupiter.api.Test;
import org.reactivestreams.Subscription;
import reactor.core.publisher.BaseSubscriber;
import reactor.core.publisher.Flux;
import reactor.core.publisher.FluxSink;
import reactor.test.StepVerifier;

class P04BackpressureTest {

    /** A producer that pushes 100 items immediately and ignores demand (like UI events or a sensor). */
    static Flux&lt;Integer&gt; overproducing() {
        return Flux.create(sink -&gt; { for (int i = 1; i &lt;= 100; i++) sink.next(i); sink.complete(); }, FluxSink.OverflowStrategy.IGNORE);
    }

    /**
     * A consumer with ZERO demand while the producer runs, which requests only afterwards. (StepVerifier would send a
     * leading thenRequest() inside onSubscribe, before Flux.create starts emitting, so no overflow would ever happen.)
     */
    static final class LateSubscriber extends BaseSubscriber&lt;Integer&gt; {
        final List&lt;Integer&gt; received = new CopyOnWriteArrayList&lt;&gt;();
        @Override protected void hookOnSubscribe(Subscription s) { /* request nothing yet */ }
        @Override protected void hookOnNext(Integer v) { received.add(v); }
    }

    @Test
    void boundedBuffer_keepsNewest10_dropsOldest() {
        var bp = new P04Backpressure();
        var consumer = new LateSubscriber();
        bp.bounded(overproducing(), 10).subscribe(consumer);   // all 100 pushed while demand = 0
        consumer.request(3);
        assertThat(consumer.received).containsExactly(91, 92, 93);
        consumer.request(Long.MAX_VALUE);
        assertThat(consumer.received).hasSize(10).endsWith(100);
        assertThat(bp.dropped).hasSize(90).startsWith(1, 2, 3);
    }

    @Test
    void drop_deliversOnlyWhatWasRequested() {
        var bp = new P04Backpressure();
        StepVerifier.create(bp.drop(overproducing()), 5).expectNext(1, 2, 3, 4, 5).verifyComplete();
        assertThat(bp.dropped).hasSize(95);
    }

    @Test
    void latest_keepsOnlyTheMostRecentValue() {
        var consumer = new LateSubscriber();
        new P04Backpressure().latest(overproducing()).subscribe(consumer);
        consumer.request(1);
        assertThat(consumer.received).containsExactly(100);
    }

    @Test
    void limitRate_requestsInBatches_neverUnbounded() {
        List&lt;Long&gt; requests = new CopyOnWriteArrayList&lt;&gt;();
        Flux&lt;Integer&gt; source = Flux.range(1, 50).doOnRequest(requests::add);
        StepVerifier.create(new P04Backpressure().paced(source)).expectNextCount(50).verifyComplete();
        assertThat(requests.get(0)).isEqualTo(10);
        assertThat(requests).allMatch(r -&gt; r &lt;= 10);
    }
}
</code></pre>

P05Batcher.java<pre><code>package com.example.reactive.playbook.codinginterview;

import java.time.Duration;
import java.util.List;
import java.util.function.Function;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

/** Problem 5: write events to the DB in batches of up to N, or every T ms, whichever comes first, one batch in flight at a time. */
public class P05Batcher {

    public record Event(int id) { }

    public static Flux&lt;Integer&gt; batchWrite(Flux&lt;Event&gt; events, int maxSize, Duration maxWait, Function&lt;List&lt;Event&gt;, Mono&lt;Integer&gt;&gt; bulkInsert) {
        return events
                .bufferTimeout(maxSize, maxWait)          // size OR time triggers a batch
                .concatMap(bulkInsert);                   // sequential writes: ordering + bounded DB load
    }
}
</code></pre> P05BatcherTest.java<pre><code>package com.example.reactive.playbook.codinginterview;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Duration;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;

class P05BatcherTest {

    @Test
    void burstFlushesBySize_trickleFlushesByTime() {
        List&lt;Integer&gt; batchSizes = new CopyOnWriteArrayList&lt;&gt;();
        StepVerifier.withVirtualTime(() -&gt; {
                    Flux&lt;P05Batcher.Event&gt; events = Flux.concat(
                            Flux.range(1, 25).map(P05Batcher.Event::new),                                           // burst
                            Flux.interval(Duration.ofSeconds(5)).take(3).map(i -&gt; new P05Batcher.Event(26 + i.intValue())));  // trickle
                    return P05Batcher.batchWrite(events, 10, Duration.ofSeconds(1), batch -&gt; {
                        batchSizes.add(batch.size());
                        return Mono.just(batch.size());
                    });
                })
                .expectNext(10, 10)                          // size-triggered, immediately
                .thenAwait(Duration.ofSeconds(1)).expectNext(5)   // time-triggered remainder of the burst
                .thenAwait(Duration.ofSeconds(30)).expectNext(1, 1, 1)
                .verifyComplete();
        assertThat(batchSizes).containsExactly(10, 10, 5, 1, 1, 1);
    }

    @Test
    void oneBatchInFlightAtATime_preservesOrder() {
        AtomicInteger inFlight = new AtomicInteger(), maxInFlight = new AtomicInteger();
        List&lt;Integer&gt; firstIds = new CopyOnWriteArrayList&lt;&gt;();
        StepVerifier.withVirtualTime(() -&gt; P05Batcher.batchWrite(Flux.range(1, 30).map(P05Batcher.Event::new), 10, Duration.ofSeconds(1),
                        batch -&gt; Mono.delay(Duration.ofMillis(300))
                                .doOnSubscribe(s -&gt; { maxInFlight.accumulateAndGet(inFlight.incrementAndGet(), Math::max); firstIds.add(batch.get(0).id()); })
                                .doOnTerminate(inFlight::decrementAndGet)
                                .thenReturn(batch.size())))
                .thenAwait(Duration.ofSeconds(5)).expectNext(10, 10, 10).verifyComplete();
        assertThat(maxInFlight.get()).isEqualTo(1);
        assertThat(firstIds).containsExactly(1, 11, 21);
    }
}
</code></pre>

P06PriceFeed.java<pre><code>package com.example.reactive.playbook.codinginterview;

import reactor.core.publisher.Flux;
import reactor.core.publisher.Sinks;

/** Problem 6: one live price feed shared by many subscribers; late joiners get the last N prices immediately. */
public class P06PriceFeed {

    public record Tick(String symbol, long priceCents) { }

    private final Sinks.Many&lt;Tick&gt; sink;

    public P06PriceFeed(int replayLast) {
        this.sink = Sinks.many().replay().limit(replayLast);          // hot + bounded replay for late subscribers
    }

    /** Producers call this; FAIL_FAST surfaces concurrent-emission bugs (use a serialized/busy-looping handler if needed). */
    public void publish(Tick t) { sink.emitNext(t, Sinks.EmitFailureHandler.FAIL_FAST); }

    public void close() { sink.emitComplete(Sinks.EmitFailureHandler.FAIL_FAST); }

    public Flux&lt;Tick&gt; ticks() { return sink.asFlux(); }               // expose as Flux: callers can't emit

    public Flux&lt;Tick&gt; ticksFor(String symbol) { return ticks().filter(t -&gt; t.symbol().equals(symbol)); }

    public int subscriberCount() { return sink.currentSubscriberCount(); }
}
</code></pre> P06PriceFeedTest.java<pre><code>package com.example.reactive.playbook.codinginterview;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import org.junit.jupiter.api.Test;
import reactor.core.Disposable;
import reactor.test.StepVerifier;

class P06PriceFeedTest {

    static P06PriceFeed.Tick t(long p) { return new P06PriceFeed.Tick("ACME", p); }

    @Test
    void lateSubscriber_getsLastThree_thenLiveTicks() {
        var feed = new P06PriceFeed(3);
        for (long p = 100; p &lt;= 105; p++) feed.publish(t(p));
        StepVerifier.create(feed.ticks().map(P06PriceFeed.Tick::priceCents).take(5))
                .expectNext(103L, 104L, 105L)                  // replayed history
                .then(() -&gt; { feed.publish(t(106)); feed.publish(t(107)); })
                .expectNext(106L, 107L)                        // live
                .verifyComplete();
    }

    @Test
    void manySubscribers_shareOneUpstream_andReceiveTheSameTicks() {
        var feed = new P06PriceFeed(1);
        List&lt;Long&gt; a = new CopyOnWriteArrayList&lt;&gt;(), b = new CopyOnWriteArrayList&lt;&gt;();
        Disposable da = feed.ticks().subscribe(x -&gt; a.add(x.priceCents()));
        Disposable db = feed.ticks().subscribe(x -&gt; b.add(x.priceCents()));
