P12CircuitBreaker.java<pre><code>package com.example.reactive.playbook.codinginterview;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.function.Function;
import reactor.core.publisher.Mono;

/** Problem 12: a reactive circuit breaker as a reusable operator: CLOSED -&gt; OPEN after N failures -&gt; HALF_OPEN after a cool-down. */
public class P12CircuitBreaker {

    public enum State { CLOSED, OPEN, HALF_OPEN }
    public static final class CallNotPermitted extends RuntimeException { CallNotPermitted() { super("circuit open"); } }

    private final int failureThreshold;
    private final Duration openFor;
    private final Clock clock;
    private State state = State.CLOSED;
    private int consecutiveFailures;
    private Instant openedAt;

    public P12CircuitBreaker(int failureThreshold, Duration openFor, Clock clock) {
        this.failureThreshold = failureThreshold; this.openFor = openFor; this.clock = clock;
    }

    /** Use with transformDeferred so the permission check happens per SUBSCRIPTION, not once at assembly. */
    public &lt;T&gt; Function&lt;Mono&lt;T&gt;, Mono&lt;T&gt;&gt; protect() {
        return source -&gt; Mono.defer(() -&gt; {
            if (!tryAcquire()) return Mono.error(new CallNotPermitted());
            return source.doOnSuccess(v -&gt; onSuccess()).doOnError(e -&gt; onFailure());
        });
    }

    private synchronized boolean tryAcquire() {
        if (state == State.OPEN &amp;&amp; !clock.instant().isBefore(openedAt.plus(openFor))) state = State.HALF_OPEN;   // allow a trial
        return state != State.OPEN;
    }

    private synchronized void onSuccess() { consecutiveFailures = 0; state = State.CLOSED; }

    private synchronized void onFailure() {
        consecutiveFailures++;
        if (state == State.HALF_OPEN || consecutiveFailures &gt;= failureThreshold) { state = State.OPEN; openedAt = clock.instant(); }
    }

    public synchronized State state() { return state; }
}
</code></pre> P12CircuitBreakerTest.java<pre><code>package com.example.reactive.playbook.codinginterview;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;

class P12CircuitBreakerTest {

    static final class MutableClock extends Clock {
        Instant now = Instant.parse("2025-01-01T00:00:00Z");
        public ZoneId getZone() { return ZoneOffset.UTC; }
        public Clock withZone(ZoneId z) { return this; }
        public Instant instant() { return now; }
    }

    final MutableClock clock = new MutableClock();
    final P12CircuitBreaker breaker = new P12CircuitBreaker(3, Duration.ofSeconds(10), clock);
    final AtomicInteger calls = new AtomicInteger();
    volatile boolean healthy = false;

    Mono&lt;String&gt; remote() {
        return Mono.defer(() -&gt; { calls.incrementAndGet(); return healthy ? Mono.just("ok") : Mono.error(new IllegalStateException("500")); })
                .transformDeferred(breaker.protect());
    }

    @Test
    void opensAfterThreshold_andStopsCallingTheDependency() {
        for (int i = 0; i &lt; 3; i++) StepVerifier.create(remote()).expectError(IllegalStateException.class).verify();
        assertThat(breaker.state()).isEqualTo(P12CircuitBreaker.State.OPEN);
        StepVerifier.create(remote()).expectError(P12CircuitBreaker.CallNotPermitted.class).verify();
        assertThat(calls.get()).isEqualTo(3);                             // the 4th call never reached the dependency
    }

    @Test
    void halfOpenTrial_success_closesTheCircuit() {
        for (int i = 0; i &lt; 3; i++) remote().onErrorResume(e -&gt; Mono.empty()).block();
        clock.now = clock.now.plusSeconds(10);
        healthy = true;
        StepVerifier.create(remote()).expectNext("ok").verifyComplete();
        assertThat(breaker.state()).isEqualTo(P12CircuitBreaker.State.CLOSED);
    }

    @Test
    void halfOpenTrial_failure_reopensImmediately() {
        for (int i = 0; i &lt; 3; i++) remote().onErrorResume(e -&gt; Mono.empty()).block();
        clock.now = clock.now.plusSeconds(11);
        StepVerifier.create(remote()).expectError(IllegalStateException.class).verify();
        assertThat(breaker.state()).isEqualTo(P12CircuitBreaker.State.OPEN);
        StepVerifier.create(remote()).expectError(P12CircuitBreaker.CallNotPermitted.class).verify();
    }

    @Test
    void successResetsTheFailureCount() {
        remote().onErrorResume(e -&gt; Mono.empty()).block();
        remote().onErrorResume(e -&gt; Mono.empty()).block();
        healthy = true;
        remote().block();
        healthy = false;
        remote().onErrorResume(e -&gt; Mono.empty()).block();
        assertThat(breaker.state()).isEqualTo(P12CircuitBreaker.State.CLOSED);   // 2 + reset + 1 &lt; 3
    }
}
