Mono&lt;String&gt; failed = Mono.error(new IllegalStateException("boom"));
Flux&lt;Integer&gt; many = Flux.just(1, 2, 3);             // 0..N elements
Flux&lt;Integer&gt; range = Flux.range(10, 3);             // 10, 11, 12
Flux&lt;String&gt; fromList = Flux.fromIterable(List.of("a", "b"));

StepVerifier.create(one).expectNext("hello").verifyComplete();
StepVerifier.create(none).verifyComplete();
StepVerifier.create(failed).verifyErrorMessage("boom");
StepVerifier.create(many).expectNext(1, 2, 3).verifyComplete();
StepVerifier.create(range).expectNext(10, 11, 12).verifyComplete();
StepVerifier.create(fromList).expectNext("a", "b").verifyComplete();
</code></pre>

flowchart LR     S[source] --&gt; A[op A] --&gt; PO{{publishOn X}} --&gt; B[op B] --&gt; C[op C]     style PO fill:#7e57c2,color:#fff <ul> <li><code>publishOn(X)</code> — switches the thread for operators below it. Position matters; you can use   it several times.</li> <li><code>subscribeOn(X)</code> — switches the thread on which the subscription (and so the source) runs.   Position doesn't matter; the one closest to the source wins.</li> </ul> publishOnsubscribeOn <pre><code>List&lt;String&gt; threads = new CopyOnWriteArrayList&lt;&gt;();
Flux.range(1, 2)
        .doOnNext(i -&gt; threads.add("before:" + Thread.currentThread().getName()))
        .publishOn(Schedulers.parallel())       // everything BELOW runs on `parallel`
        .doOnNext(i -&gt; threads.add("after:" + Thread.currentThread().getName()))
        .blockLast();

assertThat(threads).filteredOn(t -&gt; t.startsWith("before:")).noneMatch(t -&gt; t.contains("parallel"));
assertThat(threads).anyMatch(t -&gt; t.startsWith("after:parallel-"));
</code></pre> <pre><code>List&lt;String&gt; threads = new CopyOnWriteArrayList&lt;&gt;();
Mono.fromCallable(() -&gt; {
            threads.add(Thread.currentThread().getName());   // the (blocking) source
            return "data";
        })
        .subscribeOn(Schedulers.boundedElastic())            // position doesn't matter
        .map(String::toUpperCase)
        .block();

assertThat(threads).singleElement().asString().startsWith("boundedElastic-");
</code></pre>

